def is_nested_parens(paren_string: str) -> bool:
    """ Check whether all parentheses in the string are properly matched.

    >>> is_nested_parens('()()')
    True
    >>> is_nested_parens('(()())((()))')
    True
    >>> is_nested_parens('(()())((()))(')
    False
    """
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            else:
                stack.pop()
        else:
            pass
    return not stack


