def filter_by_substring_index(strings: List[str], substring: str) -> List[str]:
    """ Filter an input list of strings only for ones that contain given substring and 
    keep the original index of the substring in the item (list of 2 tuples)
    >>> filter_by_substring(['aabc', 'acbacd', 'cde'], 'a')
    [('aabc', 0), ('acbacd', 1), ('cde', -1)]
    """
    filtered = []
    for item in strings:
        sub_index = -1
        for index, value in enumerate(item):
            if value == substring:
                sub_index = index
        filtered.append((item, sub_index))

    return filtered

