def mean(numbers: List[float]) -> float:
    """ For a given list of input numbers, return the mean (average) of this
    dataset.
    >>> mean([1.0, 2.0, 3.0, 4.0])
    2.5
    """
    return sum(numbers)/len(numbers)


def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, return the median of this dataset.
    >>> median([1.0, 2.0, 3.0, 4.0])
    2.5
    """
    sorted_numbers = sorted(numbers)
    index = len(sorted_numbers) // 2

    if len(sorted_numbers) % 2 == 0:
        return mean([sorted_numbers[index - 1], sorted_numbers[index]])

    return sorted_numbers[index]

