def variance(numbers: List[float]) -> float:
    """ Return the variance of a list of input numbers.
    Variance is the mean of the squared difference between each element
    and the mean of this dataset:
    var = mean of ((x - x_mean)^2)
    >>> variance([1.0, 2.0, 3.0, 4.0])
    1.25
    """
    return mean([(x-mean(numbers))**2 for x in numbers])

def variance_of_subset(numbers: List[float]) -> float:
    """ Return the variance of a subset from a list of input numbers.
    >>> variance_of_subset([1.0, 2.0, 3.0, 4.0])
    1.25
    """
    return sum([(x-mean(numbers))**2 for x in numbers])/len(numbers)

