def get_nested_level(paren_string: str) -> int:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    return the level of nesting in the deepest group
    Ignore any spaces in the input string.
    For ex.:
    '( ) '       -> 0
    '( ) (( )) ' -> 2
    '( ) (( )( )) ' -> 3
    """
    levels = []
    for group in separate_paren_groups(paren_string):
        level = 0
        for i in group:
            if i == '(':
                level += 1
            else:
                level -= 1
        levels.append(level)
    return max(levels)

