def search_in_binary_search(a_list, target):
    """
    Write an efficient function to search a target in a sorted list.
    Return index of target if it exists else -1.

    >>> search_in_binary_search([1,2,3,4,5,6,7], 5)
    4
    >>> search_in_binary_search([1,2,3,4,5,6,7], 11)
    -1
    """
    i = 0
    j = len(a_list) - 1
    while i <= j:
        mid = (i + j) // 2
        if a_list[mid] == target:
            return mid
        elif a_list[mid] > target:
            j = mid - 1
        else:
            i = mid + 1
    return -1


